  // <<< v8 GMX trading — end of the `gx` block
  // >>> v8 Solana ↔ EVM USDC (Circle CCTP on Solana) — ONE contiguous block, every key prefixed `sc`: keep additions inside it
  scSrcIntro: ['Sur Solana, la destruction crée un petit compte qui porte le message de Circle. Son dépôt de garantie ({dep} SOL) sort de votre portefeuille avec la transaction et vous revient : le programme de Circle le libère cinq jours plus tard, et vous le récupérez ici d’un geste.', 'On Solana the burn creates a small account that carries Circle’s message. Its rent deposit ({dep} SOL) leaves your wallet with the transaction and comes back to you: Circle’s program releases it five days later, and you reclaim it here in one step.'],
  scSrcFee: ['Frais du réseau Solana pour la destruction : ≈ {fee} SOL (deux signatures : la vôtre et celle du compte de message, créée par le signataire pour cette seule transaction).', 'Solana network fee for the burn: ≈ {fee} SOL (two signatures: yours and the message account’s, created by the signer for this one transaction).'],
  scDeposit: ['Dépôt remboursable', 'Refundable deposit'], scDepositVal: ['{dep} SOL · récupérable le {date}', '{dep} SOL · reclaimable on {date}'], scDepositValEst: ['{dep} SOL · récupérable vers le {date}', '{dep} SOL · reclaimable around {date}'],
  scDepositBack: ['{dep} SOL · récupéré', '{dep} SOL · reclaimed'],
  scRecipient: ['Compte de réception', 'Receiving account'], scRecipientVal: ['votre compte de jetons USDC sur Solana', 'your USDC token account on Solana'],
  scNonceRent: ['Reçu de réception (non remboursable)', 'Receipt record (not refundable)'], scNonceRentVal: ['{rent} SOL, payés à la réception', '{rent} SOL, paid when receiving'],
  scDstIntro: ['Sur Solana, les USDC arrivent dans votre compte de jetons USDC ({acct}), jamais ailleurs. La réception se paie en SOL : frais du réseau et {rent} SOL pour le reçu que le programme de Circle conserve (non remboursable).', 'On Solana the USDC arrives in your USDC token account ({acct}), never anywhere else. Receiving is paid in SOL: the network fee and {rent} SOL for the receipt Circle’s program keeps (not refundable).'],
  scAtaMissingTitle: ['Votre portefeuille n’a pas encore de compte de jetons USDC sur Solana.', 'Your wallet has no USDC token account on Solana yet.'],
  scAtaMissing: ['Il doit exister avant toute destruction : des USDC détruits vers un compte inexistant ne pourraient pas être émis, et CCTP ne permet pas de les rediriger. Le créer est une petite transaction Solana : dépôt de {rent} SOL (il reste dans votre compte de jetons) plus les frais du réseau, approuvée avec votre clé d’accès.', 'It must exist before anything is burned: USDC burned toward an account that does not exist could not be minted, and CCTP cannot redirect it. Creating it is a small Solana transaction: a deposit of {rent} SOL (it stays in your token account) plus the network fee, approved with your passkey.'],
  scAtaCreate: ['Créer mon compte USDC sur Solana', 'Create my USDC account on Solana'], scAtaCreating: ['Création en cours : la transaction a été envoyée, le compte apparaîtra dans quelques secondes.', 'Creating: the transaction was sent, the account will appear in a few seconds.'],
