  nfTErr_destination_is_wallet: ['Le destinataire est ce portefeuille lui-même.', 'The recipient is this wallet itself.'], nfTErr_destination_is_contract_itself: ['Le destinataire est le contrat du jeton lui-même : le NFT serait perdu.', 'The recipient is the token contract itself: the NFT would be lost.'],
  nfTErr_bad_destination: ['Adresse de destinataire invalide pour ce réseau (ou adresse d’un programme / d’un compte de jeton).', 'Invalid recipient address for this network (or the address of a program / a token account).'],
