  nfTErr_contract_is_fungible_token: ['Ce contrat est un jeton fongible enregistré, pas une collection de NFT.', 'This contract is a registered fungible token, not an NFT collection.'], nfTErr_standard_changed: ['Le standard on-chain diffère de l’inventaire : actualisez le NFT.', 'The on-chain standard differs from the inventory: refresh the NFT.'],
  nfTErr_state_changed: ['L’état on-chain de cet actif a changé depuis sa lecture : actualisez le NFT.', 'The on-chain state of this asset changed since it was read: refresh the NFT.'], nfTErr_gas_too_high: ['Le transfert de cette collection demande plus de gaz que ce portefeuille n’en accorde à un envoi de NFT.', 'This collection’s transfer needs more gas than this wallet allows for an NFT transfer.'],
